package dev.starling.mobile

import android.app.Activity
import android.graphics.Typeface
import android.os.Bundle
import android.util.TypedValue
import android.view.View
import android.view.ViewGroup
import android.widget.LinearLayout
import android.widget.ScrollView
import android.widget.TextView
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat

/**
 * Starling's own license and every open-source component the app ships
 * with its license (assets/licenses/third-party-notices.json, generated by
 * the build); a row opens its full text.
 */
class LicensesActivity : Activity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        val list = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(24), dp(28), dp(24), dp(40))
        }
        val root = ScrollView(this).apply { addView(list) }
        setContentView(root)
        // Edge-to-edge as in MainActivity: clear the system bars and cutout.
        ViewCompat.setOnApplyWindowInsetsListener(root) { view, windowInsets ->
            val bars = windowInsets.getInsets(WindowInsetsCompat.Type.systemBars())
            val cutout = windowInsets.displayCutout
            view.setPadding(
                maxOf(bars.left, cutout?.safeInsetLeft ?: 0),
                maxOf(bars.top, cutout?.safeInsetTop ?: 0),
                maxOf(bars.right, cutout?.safeInsetRight ?: 0),
                maxOf(bars.bottom, cutout?.safeInsetBottom ?: 0),
            )
            WindowInsetsCompat.CONSUMED
        }

        list.addView(text(getString(R.string.licenses_heading), R.style.TextAppearance_Starling_Heading))
        list.addView(text(getString(R.string.licenses_intro), R.style.TextAppearance_Starling_Body, top = 6))

        val notices = runCatching {
            ThirdPartyNotices.parse(assets.open(ThirdPartyNotices.ASSET).bufferedReader().use { it.readText() })
        }.getOrNull()
        if (notices == null) {
            list.addView(text(getString(R.string.licenses_unavailable), R.style.TextAppearance_Starling_Body, top = 18))
            return
        }
        val starling = ThirdPartyNotices.Component(
            name = getString(R.string.app_name),
            version = BuildConfig.VERSION_NAME,
            license = "MIT",
            url = "https://github.com/sims1253/starling",
            texts = listOf(notices.starlingLicense),
        )
        list.addView(row(starling, top = 18))
        list.addView(
            text(
                getString(R.string.licenses_components, notices.components.size),
                R.style.TextAppearance_Starling_Subheading,
                top = 24,
            ),
        )
        for (component in notices.components) list.addView(row(component, top = 4))
    }

    /** A component's name, version and license; tapping it shows or hides its texts. */
    private fun row(component: ThirdPartyNotices.Component, top: Int): View {
        val body = text(
            (listOf(component.url) + component.texts).filter(String::isNotEmpty).joinToString("\n\n"),
            R.style.TextAppearance_Starling_Meta,
            top = 6,
        ).apply {
            typeface = Typeface.MONOSPACE
            setTextSize(TypedValue.COMPLEX_UNIT_SP, 11f)
            setTextIsSelectable(true)
            visibility = View.GONE
        }
        return LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(0, dp(top), 0, dp(6))
            isClickable = true
            isFocusable = true
            val ripple = TypedValue().also { theme.resolveAttribute(android.R.attr.selectableItemBackground, it, true) }
            setBackgroundResource(ripple.resourceId)
            addView(text(component.name, R.style.TextAppearance_Starling_Subheading))
            addView(
                text(
                    listOf(component.version, component.license).filter(String::isNotEmpty).joinToString(" · "),
                    R.style.TextAppearance_Starling_Meta,
                ),
            )
            addView(body)
            contentDescription = getString(R.string.licenses_row_description, component.name, component.license)
            setOnClickListener { body.visibility = if (body.visibility == View.GONE) View.VISIBLE else View.GONE }
        }
    }

    private fun text(value: String, style: Int, top: Int = 0) = TextView(this).apply {
        setTextAppearance(style)
        text = value
        layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            .apply { topMargin = dp(top) }
    }

    private fun dp(value: Int) = (value * resources.displayMetrics.density).toInt()
}
